def lemma_of(b, c, v, tok): return [base(l) for x, _, _, l, _ in by[(b, c, v)] if x == tok]
def PT(b, c, v, tok): return [NF(pointed(r)) for x, _, r, _, _ in by[(b, c, v)] if x == tok]
